			Name = "Dot",
			BackgroundColor3 = dotColor,
			Size = UDim2.fromOffset(4, 4),
			Position = UDim2.fromOffset(3, 6),
			LayoutOrder = 1,
			Parent = li,
		}, { Create.corner(999) })

		local text: string
		if item.Name then
			text = item.Name .. ":  " .. (item.Value or "")
